import java.util.*;

public class Solution {
    static List<Integer> ordem(int n, int[][] deps) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] grau = new int[n];
        for (int[] d : deps) {
            adj.get(d[0]).add(d[1]);
            grau[d[1]]++;
        }
        PriorityQueue<Integer> livres = new PriorityQueue<>();
        for (int i = 0; i < n; i++) if (grau[i] == 0) livres.add(i);
        List<Integer> out = new ArrayList<>();
        while (!livres.isEmpty()) {
            int u = livres.poll();
            out.add(u);
            for (int v : adj.get(u)) if (--grau[v] == 0) livres.add(v);
        }
        // Se sobrou alguém com grau > 0, ele está num ciclo.
        return out.size() == n ? out : List.of();
    }
}

