import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void deterministica() {
        assertEquals(List.of(0, 1, 2, 3, 4, 5), Solution.ordem(6, new int[][]{{0, 3}, {1, 3}, {3, 4}, {2, 5}}));
        assertEquals(List.of(2, 1, 0), Solution.ordem(3, new int[][]{{2, 1}, {1, 0}}));
    }

    @Test void desconexo() {
        assertEquals(List.of(0, 1, 2, 3), Solution.ordem(4, new int[][]{}));
    }

    @Test void ciclosEAutoLaco() {
        assertEquals(List.of(), Solution.ordem(3, new int[][]{{0, 1}, {1, 2}, {2, 1}}));
        assertEquals(List.of(), Solution.ordem(2, new int[][]{{1, 1}}));
    }

    @Test void respeitaDependencias() {
        var rnd = new Random(8);
        int n = 5000;
        int[][] deps = new int[20_000][];
        for (int i = 0; i < deps.length; i++) {
            int a = rnd.nextInt(n - 1);
            deps[i] = new int[]{a, a + 1 + rnd.nextInt(n - a - 1)};
        }
        List<Integer> o = Solution.ordem(n, deps);
        assertEquals(n, o.size());
        int[] pos = new int[n];
        for (int i = 0; i < n; i++) pos[o.get(i)] = i;
        for (int[] d : deps) assertTrue(pos[d[0]] < pos[d[1]]);
    }
}
